(7159864, 1098272, 174126, '<td valign="top">Nicely composed, reflections in glasses could be less distracting but good nonetheless</td>', 'Nicely composed, reflections in glasses could be less distracting but good nonetheless', '2014-01-19 17:21:21.000000', NULL, 1),
(7160001, 1097884, 155317, '<td valign="top">Great shot</td>', 'Great shot', '2014-01-19 23:24:31.000000', NULL, 1),
(7160054, 1097665, 124190, '<td valign="top">Oh shoot...I really was gonna say it takes guts to post this...no seriously...I think about my classmate from high school Mary who shot road kill....is this Mary??????? Geez THAT would be strange.   I posted a photo of a deer carcass once for a lucky thirteen challenge.....as the eviscerated deer had 13 ribs....did NOT score well....I came across it in a row of cedars planted in a 100 acre tree nursery....kinda freaked me out....but my first reaction was to photograph it....horror/fascination.... the end of another life....<br/>This one is not that hard to look at.....it''s the one covered in maggots with bulbous swollen bulging organs that kinda get me.....high mark for courage to post this.....</td>', 'Oh shoot...I really was gonna say it takes guts to post this...no seriously...I think about my classmate from high school Mary who shot road kill....is this Mary??????? Geez THAT would be strange.   I posted a photo of a deer carcass once for a lucky thirteen challenge.....as the eviscerated deer had 13 ribs....did NOT score well....I came across it in a row of cedars planted in a 100 acre tree nursery....kinda freaked me out....but my first reaction was to photograph it....horror/fascination.... the end of another life....This one is not that hard to look at.....it''s the one covered in maggots with bulbous swollen bulging organs that kinda get me.....high mark for courage to post this.....', '2014-01-20 00:20:06.000000', NULL, 1),
(7160059, 1098233, 124190, '<td valign="top">....didn''t even see his face at first.....never seen such a head dress.....thanks for the shot....high mark.....</td>', '....didn''t even see his face at first.....never seen such a head dress.....thanks for the shot....high mark.....', '2014-01-20 00:22:52.000000', NULL, 1),
